import{_ as t,o,c as s,a2 as r}from"./chunks/framework.ChTAMbUy.js";const p=JSON.parse('{"title":"Memory Stores","description":"","frontmatter":{},"headers":[],"relativePath":"1.10/agentops/memory_stores.md","filePath":"versions/1.10/agentops/memory_stores.md","lastUpdated":1795427388000}'),a={name:"1.10/agentops/memory_stores.md"};function n(l,e,d,i,c,m){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="memory-stores" tabindex="-1">Memory Stores <a class="header-anchor" href="#memory-stores" aria-label="Permalink to &quot;Memory Stores&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Documentation in progress</p><p>This page covers document management for existing RAG stores. Store deployment, configuration, and Graph Memory workflows are still being documented.</p></div><p>Memory Stores persist context for agents to retrieve through Memory MCP tools. Stores belong to the selected workspace.</p><p>The document workflow below is available only for <strong>RAG + pgvector</strong> stores, currently marked <strong>Experimental</strong>. <strong>Graphiti + Neo4j</strong> stores provide graph memory and don&#39;t have a <strong>Documents</strong> tab.</p><h2 id="open-a-store-s-documents" tabindex="-1">Open a Store&#39;s Documents <a class="header-anchor" href="#open-a-store-s-documents" aria-label="Permalink to &quot;Open a Store&#39;s Documents&quot;">​</a></h2><ol><li>Select the workspace and open <strong>Memory</strong> in the sidebar.</li><li>Under <strong>Deployed Memory Systems</strong>, open an existing <strong>RAG + pgvector</strong> store by selecting its name or <strong>Details</strong>.</li><li>Select <strong>Documents</strong>. <strong>Uploaded Documents</strong> lists files added through this workflow, not memories added through MCP tools.</li></ol><p>Only workspace owners and workspace admins can upload and delete documents. Other members, including editors, can view the list. Platform administrators also need a workspace role: the platform administrator role alone doesn&#39;t give access to a workspace&#39;s Memory stores.</p><p>The store&#39;s <strong>Traffic</strong> tab shows the calls it received through Agent Gateway. See <a href="./../platform/gateway_usage.html#traffic-on-resource-pages">Gateway Usage: Traffic on Resource Pages</a>.</p><h2 id="upload-or-replace-documents" tabindex="-1">Upload or Replace Documents <a class="header-anchor" href="#upload-or-replace-documents" aria-label="Permalink to &quot;Upload or Replace Documents&quot;">​</a></h2><ol><li>Select <strong>Add documents</strong> and choose up to 10 files. Upload starts as soon as you select them; there&#39;s no separate submit step.</li><li>Wait for <strong>Adding documents...</strong> to finish. The page reports how many documents were added, refreshes the list, and shows any per-file errors.</li><li>To replace a document, upload a file with exactly the same filename. It replaces the stored content and embeddings rather than adding a second document.</li></ol><p>Each file must be UTF-8 text with a <code>.txt</code>, <code>.md</code>, or <code>.markdown</code> extension, no larger than <strong>1 MiB per file</strong>. Empty files and binary content are rejected. PDFs and other document formats aren&#39;t supported.</p><p>A batch can partly succeed. Check the per-file errors, correct the failed files, and select them again to retry. Uploaded text becomes available through the store&#39;s existing Memory tools.</p><h2 id="delete-documents" tabindex="-1">Delete Documents <a class="header-anchor" href="#delete-documents" aria-label="Permalink to &quot;Delete Documents&quot;">​</a></h2><ol><li>In <strong>Uploaded Documents</strong>, select the checkboxes next to the files to remove.</li><li>Select <strong>Delete selected documents</strong>.</li><li>Review the filenames and confirm with <strong>Delete documents</strong>.</li></ol><p>Deletion removes the selected documents&#39; content and embeddings. Unselected documents and MCP-added memories aren&#39;t changed. Wait for <strong>Deleting documents...</strong> to finish, then check the deleted count and any errors. The list refreshes automatically; retry only the files that failed.</p>',15)])])}const g=t(a,[["render",n]]);export{p as __pageData,g as default};
